import sys

MOD = 998244353
factArr = []
invFactArr = []

def precomputeFactorials():
    global factArr, invFactArr
    factArr = [1] * 200001
    invFactArr = [1] * 200001
    for i in range(1, 200001):
        factArr[i] = (factArr[i-1] * i) % MOD
        invFactArr[i] = powMod(factArr[i], MOD - 2, MOD)

def ncr(n, r):
    return (((factArr[n] * invFactArr[r]) % MOD) * invFactArr[n - r]) % MOD

def powMod(base, exp, mod):
    res = 1
    while exp > 0:
        if (exp & 1) == 1:
            res = (res * base) % mod
        base = (base * base) % mod
        exp >>= 1
    return res

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    k = int(input_data[1])
    precomputeFactorials()
    if k > n:
        print(0)
        return
    remaining = n - k
    sum_val = 0
    for i in range(remaining + 1):
        val = (ncr(remaining, i) * powMod(remaining - i, n, MOD)) % MOD
        if i % 2 == 0:
            sum_val += val
        else:
            sum_val -= val
        sum_val %= MOD
    answer = (sum_val * ncr(n, remaining)) % MOD
    if remaining == 0:
        print(answer)
    else:
        print((2 * answer) % MOD)

if __name__ == "__main__":
    main()

